#!/data/data/com.termux/files/usr/bin/bash
set -Eeuo pipefail

ROOT="${COMPANYOS_HOME:-$HOME/companyos}"
STAMP="$(date +%Y%m%d_%H%M%S)"
BACKUP="$ROOT/.companyos_backups/candidate_intelligence_v2_$STAMP"
PATCH_TMP="$PREFIX/tmp/companyos_candidate_intelligence_v2_$STAMP.py"

cd "$ROOT"
source "$HOME/.companyos_launch_env" 2>/dev/null || true

mkdir -p "$BACKUP"
cp -a companyos/runtime/profit_opportunity_engine.py "$BACKUP/" 2>/dev/null || true

echo "============================================================"
echo " CompanyOS Candidate Intelligence + Qualification Fix V2"
echo "============================================================"

printf '%s' "" | base64 -d > "$PATCH_TMP"
python "$PATCH_TMP"
rm -f "$PATCH_TMP"

echo "[1/6] Syntax..."
python -m py_compile companyos/runtime/profit_opportunity_engine.py

echo "[2/6] Intelligence smoke tests..."
python - <<'PY'
from companyos.runtime.profit_opportunity_engine import Opportunity, candidate_is_internal_instruction, _candidate_qualification_reasons
bad=Opportunity(id="x",name="Research markets before building.",source="tests/x.json",next_action="",expected_profit=50,probability=0,readiness=50)
assert candidate_is_internal_instruction(bad)
good=Opportunity(id="y",name="Commercial lead qualification service",source="workspace/y.json",next_action="Contact 10 qualified buyers with a priced offer",expected_profit=2500,probability=55,evidence_count=2,evidence_quality=60,readiness=70,compliance_risk=10)
good.score=68
assert not candidate_is_internal_instruction(good)
assert _candidate_qualification_reasons(good)==[]
print("CANDIDATE_INTELLIGENCE_TESTS=PASS")
PY

echo "[3/6] Live candidate report..."
python - <<'PY'
import json
from companyos.runtime.profit_opportunity_engine import choose
x=choose()
print(json.dumps({
 "candidate_count":x.get("candidate_count"),
 "eligible_count":x.get("eligible_count"),
 "rejected_count":x.get("rejected_count"),
 "decision":x.get("decision"),
 "enrichment_queue_count":x.get("enrichment_queue_count"),
 "top_names":[r.get("name") for r in x.get("ranked",[])[:8]],
 "top_rejections":x.get("qualification_rejections",[])[:8],
},indent=2,default=str))
PY

echo "[4/6] Commit/push..."
git add -- companyos/runtime/profit_opportunity_engine.py
git diff --cached --quiet || git commit -m "Filter noncommercial profit candidates and expose enrichment gaps"
BRANCH="$(git branch --show-current)"
[ -n "$BRANCH" ] && git push origin "$BRANCH" || true

echo "[5/6] Restart..."
scripts/companyosctl restart || true
sleep 8

echo "[6/6] Current state..."
python - <<'PY'
import json
from pathlib import Path
from companyos.runtime.profit_opportunity_engine import choose
x=choose()
print("candidate_count =",x.get("candidate_count"))
print("eligible_count =",x.get("eligible_count"))
print("decision =",x.get("decision"))
p=Path.home()/"companyos"/".companyos_runtime"/"profit_candidate_enrichment_queue.json"
if p.exists():
 d=json.loads(p.read_text())
 print("enrichment_queue_count =",d.get("count"))
 for i,row in enumerate(d.get("candidates",[])[:10],1):
  print(i,row.get("name"),"->",", ".join(row.get("missing_or_blocking",[])))
PY

echo
scripts/companyosctl status || true
echo
echo "Backup: $BACKUP"
echo "COMPANYOS_CANDIDATE_INTELLIGENCE_QUALIFICATION_FIX_V2=PASS"
